16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.time.Period;
26	import java.time.temporal.ChronoUnit;
27	import java.util.*;
28	
29	/**
30	 * Simple JavaBean domain object representing an owner.
31	 *
32	 * @author Ken Krebs
33	 * @author Juergen Hoeller
34	 * @author Sam Brannen
35	 * @author Michael Isvy
36	 */
37	@Entity
38	@Table(name = "owners")
39	public class Owner extends Person {
40	    @Column(name = "address")
41	    @NotEmpty
42	    private String address;
43	
44	    @Column(name = "address_line1")
45	    private String addressLine1;
46	
47	    @Column(name = "address_line2")
48	    private String addressLine2;
49	
50	    @Column(name = "city")
51	    @NotEmpty
52	    private String city;
53	
54	    @Column(name = "telephone")
55	    @NotEmpty
56	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (+ followed by 8 to 15 digits)")
57	    private String telephone;
58	
59	    @Column(name = "email")
60	    private String email;
61	
62	    @Column(name = "title")
63	    private String title;
64	
65	    @Column(name = "registration_date")
66	    private LocalDate registrationDate;
67	
68	    @Column(name = "birth_date")
69	    private LocalDate birthDate;
70	
71	    @Column(name = "customer_code")
72	    private String customerCode;
73	
74	    @Column(name = "household_id")
75	    private String householdId;
76	
77	    @Column(name = "namesake_count")
78	    private Integer namesakeCount;
79	
80	    @Column(name = "postcode")
81	    private String postcode;
82	
83	    @Transient
84	    private Integer householdSize;
85	
86	    @Transient
87	    private boolean bulkSignupWarning;
88	
89	    @Transient
90	    private boolean possibleDuplicate;
91	
92	    @Transient
93	    private Integer possibleDuplicateOf;
94	
95	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
96	    private Set<Pet> pets;
97	
98	    public String getAddress() {
99	        return this.address;
100	    }
101	
102	    public void setAddress(String address) {
103	        this.address = address;
104	    }
105	
106	    public String getAddressLine1() {
107	        return this.addressLine1;
108	    }
109	
110	    public void setAddressLine1(String addressLine1) {
111	        this.addressLine1 = addressLine1;
112	    }
113	
114	    public String getAddressLine2() {
115	        return this.addressLine2;
116	    }
117	
118	    public void setAddressLine2(String addressLine2) {
119	        this.addressLine2 = addressLine2;
120	    }
121	
122	    public String getCity() {
123	        return this.city;
124	    }
125	
126	    public void setCity(String city) {
127	        this.city = city;
128	    }
129	
130	    public String getTelephone() {
131	        return this.telephone;
132	    }
133	
134	    public void setTelephone(String telephone) {
135	        this.telephone = telephone;
136	    }
137	
138	    public String getEmail() {
139	        return this.email;
140	    }
141	
142	    public void setEmail(String email) {
143	        this.email = email;
144	    }
145	
146	    public String getTitle() {
147	        return this.title;
148	    }
149	
150	    public void setTitle(String title) {
151	        this.title = title;
152	    }
153	
154	    public LocalDate getRegistrationDate() {
155	        return this.registrationDate;
156	    }
157	
158	    public void setRegistrationDate(LocalDate registrationDate) {
159	        this.registrationDate = registrationDate;
160	    }
161	
162	    public LocalDate getBirthDate() {
163	        return this.birthDate;
164	    }
165	
166	    public void setBirthDate(LocalDate birthDate) {
167	        this.birthDate = birthDate;
168	    }
169	
170	    public String getCustomerCode() {
171	        return this.customerCode;
172	    }
173	
174	    public void setCustomerCode(String customerCode) {
175	        this.customerCode = customerCode;
176	    }
177	
178	    public String getHouseholdId() {
179	        return this.householdId;
180	    }
181	
182	    public void setHouseholdId(String householdId) {
183	        this.householdId = householdId;
184	    }
185	
186	    /**
187	     * The number of owners in this owner's household (owners sharing its householdId, counting
188	     * this owner). Not a persisted column — populated by the owner pipelines (create and read)
189	     * that have repository access, and consumed only by {@link #getMembershipPoints()}. {@code
190	     * null} when it has not been resolved, which the points rule treats as a single-member
191	     * household.
192	     */
193	    @Transient
194	    public Integer getHouseholdSize() {
195	        return this.householdSize;
196	    }
197	
198	    public void setHouseholdSize(Integer householdSize) {
199	        this.householdSize = householdSize;
200	    }
201	
202	    public Integer getNamesakeCount() {
203	        return this.namesakeCount;
204	    }
205	
206	    public void setNamesakeCount(Integer namesakeCount) {
207	        this.namesakeCount = namesakeCount;
208	    }
209	
210	    public String getPostcode() {
211	        return this.postcode;
212	    }
213	
214	    public void setPostcode(String postcode) {
215	        this.postcode = postcode;
216	    }
217	
218	    /**
219	     * The owner's name formatted as {@code 'LastName, FirstName'} from the stored names.
220	     * Not persisted — derived from {@link #getLastName()} and {@link #getFirstName()}.
221	     */
222	    @Transient
223	    public String getDisplayName() {
224	        return this.getLastName() + ", " + this.getFirstName();
225	    }
226	
227	    /**
228	     * The owner's initials: the upper-cased first letters of firstName and lastName,
229	     * dot-separated with a trailing dot (e.g. {@code 'J.S.'}).
230	     * Not persisted — derived from {@link #getFirstName()} and {@link #getLastName()}.
231	     */
232	    @Transient
233	    public String getInitials() {
234	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
235	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
236	    }
237	
238	    /**
239	     * The owner's salutation: the {@link #getTitle() title} and {@link #getLastName() lastName}
240	     * separated by a single space (e.g. {@code 'DR Who'}), or just the last name when no title is
241	     * supplied. Not persisted — derived from {@link #getTitle()} and {@link #getLastName()}.
242	     */
243	    @Transient
244	    public String getSalutation() {
245	        if (this.title == null || this.title.isBlank()) {
246	            return this.getLastName();
247	        }
248	        return this.title + " " + this.getLastName();
249	    }
250	
251	    /**
252	     * The owner's {@link #getTelephone() telephone} formatted for humans: the stored E.164
253	     * value rewritten as the country code, a space, then the national digits grouped in threes
254	     * separated by spaces (e.g. {@code '+61 412 345 678'}). The known country codes are
255	     * {@code '+61'} (Australia) and {@code '+1'} (NANP); any other E.164 value is split with a
256	     * two-digit country code. {@code null} when no telephone is set or the value is not in E.164
257	     * form. The raw {@link #getTelephone() telephone} is left in E.164 form. Not persisted —
258	     * derived from {@link #getTelephone()}.
259	     */
260	    @Transient
261	    public String getTelephoneDisplay() {
262	        if (this.telephone == null || !this.telephone.matches("\\+[0-9]+")) {
263	            return null;
264	        }
265	        String digits = this.telephone.substring(1);
266	        int countryCodeLength = digits.startsWith("1") && !digits.startsWith("61") ? 1 : 2;
267	        if (digits.length() <= countryCodeLength) {
268	            return this.telephone;
269	        }
270	        String countryCode = digits.substring(0, countryCodeLength);
271	        String national = digits.substring(countryCodeLength);
272	        StringBuilder grouped = new StringBuilder();
273	        for (int i = 0; i < national.length(); i++) {
274	            if (i > 0 && i % 3 == 0) {
275	                grouped.append(' ');
276	            }
277	            grouped.append(national.charAt(i));
278	        }
279	        return "+" + countryCode + " " + grouped;
280	    }
281	
282	    /**
283	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY is
284	     * the last two digits of the {@link #getRegistrationDate() registrationDate} year
285	     * (e.g. {@code 'NSW-1A2B3C4D-M26'}).
286	     * Not persisted — derived from {@link #getCustomerCode()} and {@link #getRegistrationDate()}.
287	     */
288	    @Transient
289	    public String getMembershipNumber() {
290	        return this.customerCode + "-M" + String.format("%02d", this.registrationDate.getYear() % 100);
291	    }
292	
293	    /**
294	     * The owner's check digit: the Luhn check digit (0-9) computed over the digits contained
295	     * in the {@link #getCustomerCode() customerCode}. Non-digit characters are ignored.
296	     * Not persisted — derived from {@link #getCustomerCode()}.
297	     */
298	    @Transient
299	    public int getCheckDigit() {
300	        int sum = 0;
301	        boolean dbl = true;
302	        String code = this.customerCode == null ? "" : this.customerCode;
303	        for (int i = code.length() - 1; i >= 0; i--) {
304	            char c = code.charAt(i);
305	            if (c < '0' || c > '9') {
306	                continue;
307	            }
308	            int d = c - '0';
309	            if (dbl) {
310	                d *= 2;
311	                if (d > 9) {
312	                    d -= 9;
313	                }
314	            }
315	            sum += d;
316	            dbl = !dbl;
317	        }
318	        return (10 - (sum % 10)) % 10;
319	    }
320	
321	    /**
322	     * The owner's membership points. Starts at {@code 0}; adds {@code 2} when an
323	     * {@link #getEmail() email} is present; adds {@code 1} when {@link #getNamesakeCount()
324	     * namesakeCount} is {@code 0}; adds {@code 2} for a household of {@code 3} or more members
325	     * ({@link #getHouseholdSize() householdSize}); adds {@code 3} for a tenure of more than
326	     * {@code 365} days since the {@link #getRegistrationDate() registration date}. Not persisted
327	     * — derived from {@link #getEmail()}, {@link #getNamesakeCount()}, {@link #getHouseholdSize()}
328	     * and {@link #getRegistrationDate()}.
329	     */
330	    @Transient
331	    public int getMembershipPoints() {
332	        int points = 0;
333	        boolean hasEmail = this.email != null && !this.email.isBlank();
334	        if (hasEmail) {
335	            points += 2;
336	        }
337	        boolean uniqueName = this.namesakeCount != null && this.namesakeCount == 0;
338	        if (uniqueName) {
339	            points += 1;
340	        }
341	        if (this.householdSize != null && this.householdSize >= 3) {
342	            points += 2;
343	        }
344	        if (this.registrationDate != null
345	                && ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now()) > 365) {
346	            points += 3;
347	        }
348	        return points;
349	    }
350	
351	    /**
352	     * The owner's numeric membership level, mapped from {@link #getMembershipPoints()
353	     * membershipPoints}: {@code 1} for {@code 0-1} points, {@code 2} for {@code 2-3},
354	     * {@code 3} for {@code 4-5} and {@code 4} for {@code 6} or more. Not persisted — derived
355	     * from {@link #getMembershipPoints()}.
356	     */
357	    @Transient
358	    public int getMembershipLevel() {
359	        int points = getMembershipPoints();
360	        if (points >= 6) {
361	            return 4;
362	        }
363	        if (points >= 4) {
364	            return 3;
365	        }
366	        if (points >= 2) {
367	            return 2;
368	        }
369	        return 1;
370	    }
371	
372	    /**
373	     * Fixed city-to-region table used as the fall-back when deriving an owner's region.
374	     */
375	    private static final Map<String, String> CITY_REGION = Map.of(
376	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
377	
378	    /**
379	     * Region -> inclusive 4-digit postcode range {low, high}, the primary source for
380	     * deriving an owner's region (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
381	     */
382	    private static final Map<String, int[]> REGION_RANGE = Map.of(
383	        "NSW", new int[] {2000, 2099},
384	        "VIC", new int[] {3000, 3099},
385	        "QLD", new int[] {4000, 4099});
386	
387	    /**
388	     * Fixed region -> IANA timezone table (NSW->Australia/Sydney, VIC->Australia/Melbourne,
389	     * QLD->Australia/Brisbane), the single authority for {@link #getTimezone()}.
390	     */
391	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
392	        "NSW", "Australia/Sydney",
393	        "VIC", "Australia/Melbourne",
394	        "QLD", "Australia/Brisbane");
395	
396	    /**
397	     * The canonical region for a postcode/city pair, derived first from {@code postcode} by range
398	     * ({@link #regionForPostcode}), falling back to the fixed city table ({@link #regionForCity})
399	     * when the postcode is absent or in no known range, or {@code 'UNKNOWN'} when neither matches.
400	     * Preferring the postcode disambiguates cities that share a name. This is the REGION prefix of
401	     * the owner's {@link #getCustomerCode() customerCode}, so the create pipeline and
402	     * {@link #getLocality() locality} agree on it. The single authority on the region rule, reused
403	     * by the owner pipelines (e.g. postcode validation) rather than copied.
404	     */
405	    public static String regionFor(String postcode, String city) {
406	        String region = regionForPostcode(postcode);
407	        if (region != null) {
408	            return region;
409	        }
410	        String cityRegion = regionForCity(city);
411	        return cityRegion != null ? cityRegion : "UNKNOWN";
412	    }
413	
414	    /** The canonical region for a city by exact name match (Sydney->NSW, Melbourne->VIC,
415	     * Brisbane->QLD), or {@code null} when the city has no known region. */
416	    public static String regionForCity(String city) {
417	        return city == null ? null : CITY_REGION.get(city);
418	    }
419	
420	    /** Region whose inclusive range contains the given postcode (NSW 2000-2099, VIC 3000-3099,
421	     * QLD 4000-4099), or {@code null} when the postcode is absent, not 4 digits, or in no known
422	     * range. */
423	    public static String regionForPostcode(String postcode) {
424	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
425	            return null;
426	        }
427	        int value = Integer.parseInt(postcode);
428	        for (Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
429	            int[] range = entry.getValue();
430	            if (value >= range[0] && value <= range[1]) {
431	                return entry.getKey();
432	            }
433	        }
434	        return null;
435	    }
436	
437	    /**
438	     * The owner's locality: the REGION prefix of the {@link #getCustomerCode() customerCode}
439	     * (the portion before the first {@code '-'}), which the create pipeline derives from the
440	     * postcode-and-city region. {@code 'UNKNOWN'} when no customerCode is set. Not persisted —
441	     * derived from {@link #getCustomerCode()}.
442	     */
443	    @Transient
444	    public String getLocality() {
445	        if (this.customerCode == null) {
446	            return "UNKNOWN";
447	        }
448	        int dash = this.customerCode.indexOf('-');
449	        return dash <= 0 ? "UNKNOWN" : this.customerCode.substring(0, dash);
450	    }
451	
452	    /**
453	     * The owner's timezone: the IANA name for the owner's {@link #getLocality() locality}/region
454	     * from the fixed region-to-timezone table (NSW->Australia/Sydney, VIC->Australia/Melbourne,
455	     * QLD->Australia/Brisbane), or {@code null} when the region has no mapped timezone. Not
456	     * persisted — derived from {@link #getLocality()}.
457	     */
458	    @Transient
459	    public String getTimezone() {
460	        return REGION_TIMEZONE.get(getLocality());
461	    }
462	
463	    /**
464	     * Whether more than 80 owners had already been created today when this response was
465	     * built. Not persisted — populated for the response by the create and fetch pipelines
466	     * and defaults to {@code false} so every owner serialization carries the flag.
467	     */
468	    @Transient
469	    public boolean isBulkSignupWarning() {
470	        return this.bulkSignupWarning;
471	    }
472	
473	    public void setBulkSignupWarning(boolean bulkSignupWarning) {
474	        this.bulkSignupWarning = bulkSignupWarning;
475	    }
476	
477	    /**
478	     * Whether this owner is a possible (soft) duplicate: not a hard duplicate, but shares an
479	     * existing owner's last name and postcode with a different telephone. Not persisted —
480	     * populated for the response by the create and fetch pipelines and defaults to
481	     * {@code false} so every owner serialization carries the flag.
482	     */
483	    @Transient
484	    public boolean isPossibleDuplicate() {
485	        return this.possibleDuplicate;
486	    }
487	
488	    public void setPossibleDuplicate(boolean possibleDuplicate) {
489	        this.possibleDuplicate = possibleDuplicate;
490	    }
491	
492	    /**
493	     * The id of the existing owner this owner possibly duplicates (shared last name and
494	     * postcode, different telephone), or {@code null} when it is not a possible duplicate.
495	     * Not persisted — populated for the response alongside {@link #isPossibleDuplicate()}.
496	     */
497	    @Transient
498	    public Integer getPossibleDuplicateOf() {
499	        return this.possibleDuplicateOf;
500	    }
501	
502	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
503	        this.possibleDuplicateOf = possibleDuplicateOf;
504	    }
505	
506	    /**
507	     * The owner's preferred contact channel: {@code 'EMAIL'} when an {@link #getEmail() email}
508	     * is present, otherwise {@code 'PHONE'}.
509	     * Not persisted — derived from {@link #getEmail()}.
510	     */
511	    @Transient
512	    public String getContactPreference() {
513	        boolean hasEmail = this.email != null && !this.email.isBlank();
514	        return hasEmail ? "EMAIL" : "PHONE";
515	    }
516	
517	    /**
518	     * The owner's age band as of the {@link #getRegistrationDate() registrationDate}, derived
519	     * from {@link #getBirthDate() birthDate}: {@code 'MINOR'} when under 18, {@code 'ADULT'} for
520	     * 18 to 64 inclusive, {@code 'SENIOR'} for 65 and over. {@code null} when no birthDate is
521	     * supplied. Not persisted — derived from {@link #getBirthDate()} and
522	     * {@link #getRegistrationDate()}.
523	     */
524	    @Transient
525	    public String getAgeBand() {
526	        if (this.birthDate == null || this.registrationDate == null) {
527	            return null;
528	        }
529	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
530	        if (age < 18) {
531	            return "MINOR";
532	        }
533	        return age < 65 ? "ADULT" : "SENIOR";
534	    }
535	
536	    protected Set<Pet> getPetsInternal() {
537	        if (this.pets == null) {
538	            this.pets = new HashSet<>();
539	        }
540	        return this.pets;
541	    }
542	
543	    protected void setPetsInternal(Set<Pet> pets) {
544	        this.pets = pets;
545	    }
546	
547	    public List<Pet> getPets() {
548	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
549	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
550	        return Collections.unmodifiableList(sortedPets);
551	    }
552	
553	    public void setPets(List<Pet> pets) {
554	        this.pets = new HashSet<>(pets);
555	    }
556	
557	    public void addPet(Pet pet) {
558	        getPetsInternal().add(pet);
559	        pet.setOwner(this);
560	    }
561	
562	    /**
563	     * Return the Pet with the given name, or null if none found for this Owner.
564	     *
565	     * @param name to test
566	     * @return true if pet name is already in use
567	     */
568	    public Pet getPet(String name) {
569	        return getPet(name, false);
570	    }
571	
572	    /**
573	     * Return the Pet with the given name, or null if none found for this Owner.
574	     *
575	     * @param name to test
576	     * @return true if pet name is already in use
577	     */
578	    public Pet getPet(String name, boolean ignoreNew) {
579	        name = name.toLowerCase();
580	        for (Pet pet : getPetsInternal()) {
581	            if (!ignoreNew || !pet.isNew()) {
582	                String compName = pet.getName();
583	                compName = compName.toLowerCase();
584	                if (compName.equals(name)) {
585	                    return pet;
586	                }
587	            }
588	        }
589	        return null;
590	    }
591	
592	    public Pet getPet(Integer petId) {
593	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
594	    }
595	
596	    @Override
597	    public String toString() {
598	        return new ToStringCreator(this)
599	
600	            .append("id", this.getId())
601	            .append("new", this.isNew())
602	            .append("lastName", this.getLastName())
603	            .append("firstName", this.getFirstName())
604	            .append("address", this.address)
605	            .append("city", this.city)
606	            .append("telephone", this.telephone)
607	            .toString();
608	    }
609	}
